  "kiosk-posm-45": {"descriptionVi":"Gian hàng hội chợ đặc sản khung gỗ nan, backdrop in tranh sông nước, kệ trưng bày và quầy tròn hắt LED chân trong nhà triển lãm.","descriptionEn":"Trade fair booth for regional specialties with a slatted timber frame, printed river-scene backdrop, display shelving and a round counter with an LED-lit base in an exhibition hall.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-45-imagegen-20261018.webp","sha256":"c273d3a28c882e0238f79b489fcebad32aa76f2c77bc4232cca742555575459d","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd387-5cf4-83ec-b31c-b03f2e56c353); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 80c1f1ee99068e33f1917a836ee770471544645e017c3ea4d58c2ac490362188."},
  "kiosk-posm-46": {"descriptionVi":"Backdrop sân khấu hội nghị in tranh vườn dừa, tấm cắt CNC hình lá viền LED hắt sáng, ốp nan gỗ hai bên trong phòng hội nghị khách sạn.","descriptionEn":"Conference stage backdrop printed with a coconut grove scene, CNC-cut leaf panels with LED edge lighting and timber slat side panels in a hotel ballroom.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-46-imagegen-20261018.webp","sha256":"b4b7e5aae8871b3a331fc6f91c4bc976d5977b00983f45a9d9e5d6148a4a49b5","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-hoi-nghi-1; original SHA256 6afa6447a8fe463d30ba6121c57c00667e5b3a2caa08ff1721f12e9f7f94bd84; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-47": {"descriptionVi":"Backdrop khai trương hình hoa sen nhiều lớp cánh cắt CNC hắt LED, chữ nổi tên cửa hàng, đặt trên thảm hồng trước cửa hàng mỹ phẩm.","descriptionEn":"Grand-opening backdrop shaped as a layered lotus with CNC-cut LED-backlit petals and raised store lettering, set on a pink carpet outside a cosmetics shop.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-47-imagegen-20261018.webp","sha256":"53647e1a278146046e7c5584bd039a126fa35ba88c6fa2b84ddfdfd4c822b21f","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-khai-truong-1; original SHA256 45ae2aada72fb7cb2f4ef319b9141e54d8f0319580515abf96d7a17517a4bbee; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-48": {"descriptionVi":"Backdrop tường nhà hàng chạm nổi phong cảnh sông nước, chữ nổi hắt sáng LED, khung tre và đèn LED viền chân trong nhà hàng ven sông.","descriptionEn":"Restaurant feature-wall backdrop with a relief river landscape, LED halo-lit raised lettering, bamboo framing and LED base lighting in a riverside restaurant.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-48-imagegen-20261018.webp","sha256":"e7cf1b44c3a2f376b0ba36b949c012cff021b49ef09efe17a01a65011b8000f3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-nha-hang-1; original SHA256 c15b3214f07c019e12d42e10e7163a23ba718fe5ff23082a638fcbb4150e5833; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-49": {"descriptionVi":"Backdrop showroom vòm phù điêu sóng và hàng dừa, chữ nổi tên thương hiệu, ốp nan gỗ và hốc kệ hắt LED sau quầy cửa hàng sản phẩm từ dừa.","descriptionEn":"Showroom backdrop with an arched relief of waves and palms, raised brand lettering, timber slat cladding and LED-lit shelf niches behind the counter of a coconut-products store.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-49-imagegen-20261018.webp","sha256":"edc0c8d9d9872fd91f1482f98eb34defd810daec8958c2f7ae34b2e82279f68b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-showroom-1; original SHA256 c0940bdb6e2902e67bb76fc283bc1a748fc090dd3192f6fd05a136ab01c66dc3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
